def ask_stream(self, prompt: str, role: str='user', convo_id: str='default', model: str=None, pass_history: bool=True, **kwargs):
    """
        Ask a question
        """
    if convo_id not in self.conversation:
        self.reset(convo_id=convo_id, system_prompt=self.system_prompt)
    self.add_to_conversation(prompt, 'user', convo_id=convo_id)
    self.__truncate_conversation(convo_id=convo_id)
    if os.environ.get('API_URL') and os.environ.get('MODEL_NAME'):
        url = os.environ.get('API_URL') + 'openai/deployments/' + os.environ.get('MODEL_NAME') + '/chat/completions?api-version=2023-05-15'
        headers = {'Content-Type': 'application/json', 'api-key': self.api_key}
    else:
        url = os.environ.get('API_URL') or 'https://api.openai.com/v1/chat/completions'
        headers = {'Authorization': f"Bearer {kwargs.get('api_key', self.api_key)}"}
    response = self.session.post(url, headers=headers, json={'model': os.environ.get('MODEL_NAME') or model or self.engine, 'messages': self.conversation[convo_id] if pass_history else [prompt], 'stream': True, 'temperature': kwargs.get('temperature', self.temperature), 'top_p': kwargs.get('top_p', self.top_p), 'presence_penalty': kwargs.get('presence_penalty', self.presence_penalty), 'frequency_penalty': kwargs.get('frequency_penalty', self.frequency_penalty), 'n': kwargs.get('n', self.reply_count), 'user': role, 'max_tokens': min(self.get_max_tokens(convo_id=convo_id), kwargs.get('max_tokens', self.max_tokens))}, timeout=kwargs.get('timeout', self.timeout), stream=True)
    if response.status_code != 200:
        raise t.APIConnectionError(f'{response.status_code} {response.reason} {response.text}')
    response_role: str or None = None
    full_response: str = ''
    for line in response.iter_lines():
        if not line:
            continue
        line = line.decode('utf-8')[6:]
        if line == '[DONE]':
            break
        resp: dict = json.loads(line)
        choices = resp.get('choices')
        if not choices:
            continue
        delta = choices[0].get('delta')
        if not delta:
            continue
        if 'role' in delta:
            response_role = delta['role']
        if 'content' in delta:
            content = delta['content']
            full_response += content
            yield content
    self.add_to_conversation(full_response, response_role, convo_id=convo_id)

