class ChatbotCLI(Chatbot):
    """
    Command Line Interface for Chatbot
    """

    def print_config(self, convo_id: str='default') -> None:
        """
        Prints the current configuration
        """
        print(f"\nChatGPT Configuration:\n  Conversation ID:  {convo_id}\n  Messages:         {len(self.conversation[convo_id])}\n  Tokens used:      {(num_tokens := self.get_token_count(convo_id))} / {self.max_tokens}\n  Cost:             {'${:.5f}'.format(num_tokens / 1000 * 0.002)}\n  Engine:           {self.engine}\n  Temperature:      {self.temperature}\n  Top_p:            {self.top_p}\n  Reply count:      {self.reply_count}\n            ")

    def print_help(self) -> None:
        """
        Prints the help message
        """
        print('\nCommands:\n  !help             Display this message\n  !rollback n       Rollback the conversation by n messages\n  !save file [keys] Save the Chatbot configuration to a JSON file\n  !load file [keys] Load the Chatbot configuration from a JSON file\n  !reset            Reset the conversation\n  !exit             Quit chat\n\nConfig Commands:\n  !config           Display the current config\n  !temperature n    Set the temperature to n\n  !top_p n          Set the top_p to n\n  !reply_count n    Set the reply_count to n\n  !engine engine    Sets the chat model to engine\n\nExamples:\n  !save c.json               Saves all ChatbotGPT class variables to c.json\n  !save c.json engine top_p  Saves only temperature and top_p to c.json\n  !load c.json not engine    Loads all but engine from c.json\n  !load c.json session       Loads session proxies from c.json\n\n\n  ')

    def handle_commands(self, prompt: str, convo_id: str='default') -> bool:
        """
        Handle chatbot commands
        """
        (command, *value) = prompt.split(' ')
        if command == '!help':
            self.print_help()
        elif command == '!exit':
            sys.exit()
        elif command == '!reset':
            self.reset(convo_id=convo_id)
            print('\nConversation has been reset')
        elif command == '!config':
            self.print_config(convo_id=convo_id)
        elif command == '!rollback':
            self.rollback(int(value[0]), convo_id=convo_id)
            print(f'\nRolled back by {value[0]} messages')
        elif command == '!save':
            self.save(*value)
            print(f"Saved {(', '.join(value[1:]) if len(value) > 1 else 'all')} keys to {value[0]}")
        elif command == '!load':
            self.load(*value)
            print(f"Loaded {(', '.join(value[1:]) if len(value) > 1 else 'all')} keys from {value[0]}")
        elif command == '!temperature':
            self.temperature = float(value[0])
            print(f'\nTemperature set to {value[0]}')
        elif command == '!top_p':
            self.top_p = float(value[0])
            print(f'\nTop_p set to {value[0]}')
        elif command == '!reply_count':
            self.reply_count = int(value[0])
            print(f'\nReply count set to {value[0]}')
        elif command == '!engine':
            if len(value) > 0:
                self.engine = value[0]
            print(f'\nEngine set to {self.engine}')
        else:
            return False
        return True

